const fs = require('fs');
const axios = require('axios');
const path = require('path');

(async () => {
  try {
    const envPath = path.resolve(process.cwd(), '.env.test');
    if (!fs.existsSync(envPath)) {
      console.error('.env.test not found');
      process.exit(1);
    }
    const content = fs.readFileSync(envPath, 'utf8');
    const lines = content.split(/\r?\n/).filter(Boolean);
    const data = {};
    for (const line of lines) {
      const [key, value] = line.split('=');
      if (key && value !== undefined) {
        data[key] = value;
      }
    }
    const url = 'http://localhost:47301/api/ci-secret-sync';
    const res = await axios.post(url, data, {headers: {'Content-Type': 'application/json'}});
    console.log('Posted secrets:', res.status);
  } catch (err) {
    console.error('Error posting secrets:', err.message);
    process.exit(1);
  }
})();

